13		"github.com/MakeNowJust/heredoc"
14		"github.com/cli/cli/v2/api"
15		fd "github.com/cli/cli/v2/internal/featuredetection"
16		"github.com/cli/cli/v2/internal/ghinstance"
17		"github.com/cli/cli/v2/internal/ghrepo"
18		"github.com/cli/cli/v2/pkg/cmdutil"
