25	type iprompter interface {
26		MultiSelect(prompt string, defaults []string, options []string) ([]int, error)
27		Input(string, string) (string, error)
28		Confirm(string, bool) (bool, error)
29		Select(string, string, []string) (int, error)
30	}
31	
32	const (
33		allowMergeCommits = "Allow Merge Commits"
34		allowSquashMerge  = "Allow Squash Merging"
35		allowRebaseMerge  = "Allow Rebase Merging"
36	
37		optionAllowForking      = "Allow Forking"
38		optionDefaultBranchName = "Default Branch Name"
39		optionDescription       = "Description"
40		optionHomePageURL       = "Home Page URL"
41		optionIssues            = "Issues"
42		optionMergeOptions      = "Merge Options"
43		optionProjects          = "Projects"
44		optionDiscussions       = "Discussions"
45		optionTemplateRepo      = "Template Repository"
46		optionTopics            = "Topics"
47		optionVisibility        = "Visibility"
48		optionWikis             = "Wikis"
49	)
50	
51	type EditOptions struct {
52		HTTPClient      *http.Client
53		Repository      ghrepo.Interface
54		IO              *iostreams.IOStreams
55		Edits           EditRepositoryInput
56		AddTopics       []string
57		RemoveTopics    []string
58		InteractiveMode bool
59		Detector        fd.Detector
60		Prompter        iprompter
61		// Cache of current repo topics to avoid retrieving them
62		// in multiple flows.
63		topicsCache []string
64	}
