66	type EditRepositoryInput struct {
67		AllowForking        *bool   `json:"allow_forking,omitempty"`
68		AllowUpdateBranch   *bool   `json:"allow_update_branch,omitempty"`
69		DefaultBranch       *string `json:"default_branch,omitempty"`
70		DeleteBranchOnMerge *bool   `json:"delete_branch_on_merge,omitempty"`
71		Description         *string `json:"description,omitempty"`
72		EnableAutoMerge     *bool   `json:"allow_auto_merge,omitempty"`
73		EnableIssues        *bool   `json:"has_issues,omitempty"`
74		EnableMergeCommit   *bool   `json:"allow_merge_commit,omitempty"`
75		EnableProjects      *bool   `json:"has_projects,omitempty"`
76		EnableDiscussions   *bool   `json:"has_discussions,omitempty"`
77		EnableRebaseMerge   *bool   `json:"allow_rebase_merge,omitempty"`
78		EnableSquashMerge   *bool   `json:"allow_squash_merge,omitempty"`
79		EnableWiki          *bool   `json:"has_wiki,omitempty"`
80		Homepage            *string `json:"homepage,omitempty"`
81		IsTemplate          *bool   `json:"is_template,omitempty"`
82		Visibility          *string `json:"visibility,omitempty"`
83	}
84	
85	func NewCmdEdit(f *cmdutil.Factory, runF func(options *EditOptions) error) *cobra.Command {
86		opts := &EditOptions{
87			IO:       f.IOStreams,
88			Prompter: f.Prompter,
89		}
90	
91		cmd := &cobra.Command{
92			Use:   "edit [<repository>]",
93			Short: "Edit repository settings",
94			Annotations: map[string]string{
95				"help:arguments": heredoc.Doc(`
96					A repository can be supplied as an argument in any of the following formats:
97					- "OWNER/REPO"
98					- by URL, e.g. "https://github.com/OWNER/REPO"
99				`),
100			},
101			Long: heredoc.Docf(`
102				Edit repository settings.
103	
104				To toggle a setting off, use the %[1]s--<flag>=false%[1]s syntax.
105	
106				Note that changing repository visibility to private will cause loss of stars and watchers.
107			`, "`"),
108			Args: cobra.MaximumNArgs(1),
109			Example: heredoc.Doc(`
110				# enable issues and wiki
111				gh repo edit --enable-issues --enable-wiki
112	
113				# disable projects
114				gh repo edit --enable-projects=false
115			`),
116			RunE: func(cmd *cobra.Command, args []string) error {
117				if len(args) > 0 {
118					var err error
119					opts.Repository, err = ghrepo.FromFullName(args[0])
120					if err != nil {
121						return err
122					}
123				} else {
124					var err error
125					opts.Repository, err = f.BaseRepo()
126					if err != nil {
127						return err
128					}
129				}
130	
131				if httpClient, err := f.HttpClient(); err == nil {
132					opts.HTTPClient = httpClient
133				} else {
134					return err
135				}
136	
137				if cmd.Flags().NFlag() == 0 {
138					opts.InteractiveMode = true
139				}
140	
141				if opts.InteractiveMode && !opts.IO.CanPrompt() {
142					return cmdutil.FlagErrorf("specify properties to edit when not running interactively")
143				}
144	
145				if runF != nil {
146					return runF(opts)
147				}
148				return editRun(cmd.Context(), opts)
149			},
150		}
151	
152		cmdutil.NilStringFlag(cmd, &opts.Edits.Description, "description", "d", "Description of the repository")
153		cmdutil.NilStringFlag(cmd, &opts.Edits.Homepage, "homepage", "h", "Repository home page `URL`")
154		cmdutil.NilStringFlag(cmd, &opts.Edits.DefaultBranch, "default-branch", "", "Set the default branch `name` for the repository")
155		cmdutil.NilStringFlag(cmd, &opts.Edits.Visibility, "visibility", "", "Change the visibility of the repository to {public,private,internal}")
156		cmdutil.NilBoolFlag(cmd, &opts.Edits.IsTemplate, "template", "", "Make the repository available as a template repository")
157		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableIssues, "enable-issues", "", "Enable issues in the repository")
158		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableProjects, "enable-projects", "", "Enable projects in the repository")
159		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableWiki, "enable-wiki", "", "Enable wiki in the repository")
160		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableDiscussions, "enable-discussions", "", "Enable discussions in the repository")
161		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableMergeCommit, "enable-merge-commit", "", "Enable merging pull requests via merge commit")
162		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableSquashMerge, "enable-squash-merge", "", "Enable merging pull requests via squashed commit")
163		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableRebaseMerge, "enable-rebase-merge", "", "Enable merging pull requests via rebase")
164		cmdutil.NilBoolFlag(cmd, &opts.Edits.EnableAutoMerge, "enable-auto-merge", "", "Enable auto-merge functionality")
165		cmdutil.NilBoolFlag(cmd, &opts.Edits.DeleteBranchOnMerge, "delete-branch-on-merge", "", "Delete head branch when pull requests are merged")
166		cmdutil.NilBoolFlag(cmd, &opts.Edits.AllowForking, "allow-forking", "", "Allow forking of an organization repository")
167		cmdutil.NilBoolFlag(cmd, &opts.Edits.AllowUpdateBranch, "allow-update-branch", "", "Allow a pull request head branch that is behind its base branch to be updated")
168		cmd.Flags().StringSliceVar(&opts.AddTopics, "add-topic", nil, "Add repository topic")
169		cmd.Flags().StringSliceVar(&opts.RemoveTopics, "remove-topic", nil, "Remove repository topic")
170	
171		return cmd
172	}
173	
174	func editRun(ctx context.Context, opts *EditOptions) error {
175		repo := opts.Repository
176	
177		if opts.InteractiveMode {
178			detector := opts.Detector
179			if detector == nil {
180				cachedClient := api.NewCachedHTTPClient(opts.HTTPClient, time.Hour*24)
181				detector = fd.NewDetector(cachedClient, repo.RepoHost())
182			}
183			repoFeatures, err := detector.RepositoryFeatures()
184			if err != nil {
185				return err
186			}
187	
188			apiClient := api.NewClientFromHTTP(opts.HTTPClient)
189			fieldsToRetrieve := []string{
190				"defaultBranchRef",
191				"deleteBranchOnMerge",
192				"description",
193				"hasIssuesEnabled",
194				"hasProjectsEnabled",
195				"hasWikiEnabled",
196				// TODO: GitHub Enterprise Server does not support has_discussions yet
197				// "hasDiscussionsEnabled",
198				"homepageUrl",
199				"isInOrganization",
200				"isTemplate",
201				"mergeCommitAllowed",
202				"rebaseMergeAllowed",
203				"repositoryTopics",
204				"stargazerCount",
205				"squashMergeAllowed",
206				"watchers",
207			}
208			if repoFeatures.VisibilityField {
209				fieldsToRetrieve = append(fieldsToRetrieve, "visibility")
210			}
211			if repoFeatures.AutoMerge {
212				fieldsToRetrieve = append(fieldsToRetrieve, "autoMergeAllowed")
213			}
214	
215			opts.IO.StartProgressIndicator()
216			fetchedRepo, err := api.FetchRepository(apiClient, opts.Repository, fieldsToRetrieve)
217			opts.IO.StopProgressIndicator()
218			if err != nil {
219				return err
220			}
221			err = interactiveRepoEdit(opts, fetchedRepo)
222			if err != nil {
223				return err
224			}
225		}
226	
227		apiPath := fmt.Sprintf("repos/%s/%s", repo.RepoOwner(), repo.RepoName())
228	
229		body := &bytes.Buffer{}
230		enc := json.NewEncoder(body)
231		if err := enc.Encode(opts.Edits); err != nil {
232			return err
233		}
234	
235		g := errgroup.Group{}
236	
237		if body.Len() > 3 {
238			g.Go(func() error {
239				apiClient := api.NewClientFromHTTP(opts.HTTPClient)
240				_, err := api.CreateRepoTransformToV4(apiClient, repo.RepoHost(), "PATCH", apiPath, body)
241				return err
242			})
243		}
244	
245		if len(opts.AddTopics) > 0 || len(opts.RemoveTopics) > 0 {
246			g.Go(func() error {
247				// opts.topicsCache gets populated in interactive mode
248				if !opts.InteractiveMode {
249					var err error
250					opts.topicsCache, err = getTopics(ctx, opts.HTTPClient, repo)
251					if err != nil {
252						return err
253					}
254				}
255				oldTopics := set.NewStringSet()
256				oldTopics.AddValues(opts.topicsCache)
257	
258				newTopics := set.NewStringSet()
259				newTopics.AddValues(opts.topicsCache)
260				newTopics.AddValues(opts.AddTopics)
261				newTopics.RemoveValues(opts.RemoveTopics)
262	
263				if oldTopics.Equal(newTopics) {
264					return nil
265				}
266				return setTopics(ctx, opts.HTTPClient, repo, newTopics.ToSlice())
267			})
268		}
269	
270		err := g.Wait()
271		if err != nil {
272			return err
273		}
274	
275		if opts.IO.IsStdoutTTY() {
276			cs := opts.IO.ColorScheme()
277			fmt.Fprintf(opts.IO.Out,
278				"%s Edited repository %s\n",
279				cs.SuccessIcon(),
280				ghrepo.FullName(repo))
281		}
282	
283		return nil
284	}
