286	func interactiveChoice(p iprompter, r *api.Repository) ([]string, error) {
287		options := []string{
288			optionDefaultBranchName,
289			optionDescription,
290			optionHomePageURL,
291			optionIssues,
292			optionMergeOptions,
293			optionProjects,
294			// TODO: GitHub Enterprise Server does not support has_discussions yet
295			// optionDiscussions,
296			optionTemplateRepo,
297			optionTopics,
298			optionVisibility,
299			optionWikis,
300		}
301		if r.IsInOrganization {
302			options = append(options, optionAllowForking)
303		}
304		var answers []string
305		selected, err := p.MultiSelect("What do you want to edit?", nil, options)
306		if err != nil {
307			return nil, err
308		}
309		for _, i := range selected {
310			answers = append(answers, options[i])
311		}
312	
313		return answers, err
314	}
315	
316	func interactiveRepoEdit(opts *EditOptions, r *api.Repository) error {
317		for _, v := range r.RepositoryTopics.Nodes {
318			opts.topicsCache = append(opts.topicsCache, v.Topic.Name)
319		}
320		p := opts.Prompter
321		choices, err := interactiveChoice(p, r)
322		if err != nil {
323			return err
324		}
325		for _, c := range choices {
326			switch c {
327			case optionDescription:
328				answer, err := p.Input("Description of the repository", r.Description)
329				if err != nil {
330					return err
331				}
332				opts.Edits.Description = &answer
333			case optionHomePageURL:
334				a, err := p.Input("Repository home page URL", r.HomepageURL)
335				if err != nil {
336					return err
337				}
338				opts.Edits.Homepage = &a
339			case optionTopics:
340				addTopics, err := p.Input("Add topics?(csv format)", "")
341				if err != nil {
342					return err
343				}
344				if len(strings.TrimSpace(addTopics)) > 0 {
345					opts.AddTopics = parseTopics(addTopics)
346				}
347	
348				if len(opts.topicsCache) > 0 {
349					selected, err := p.MultiSelect("Remove Topics", nil, opts.topicsCache)
350					if err != nil {
351						return err
352					}
353					for _, i := range selected {
354						opts.RemoveTopics = append(opts.RemoveTopics, opts.topicsCache[i])
355					}
356				}
357			case optionDefaultBranchName:
358				name, err := p.Input("Default branch name", r.DefaultBranchRef.Name)
359				if err != nil {
360					return err
361				}
362				opts.Edits.DefaultBranch = &name
363			case optionWikis:
364				c, err := p.Confirm("Enable Wikis?", r.HasWikiEnabled)
365				if err != nil {
366					return err
367				}
368				opts.Edits.EnableWiki = &c
369			case optionIssues:
370				a, err := p.Confirm("Enable Issues?", r.HasIssuesEnabled)
371				if err != nil {
372					return err
373				}
374				opts.Edits.EnableIssues = &a
375			case optionProjects:
376				a, err := p.Confirm("Enable Projects?", r.HasProjectsEnabled)
377				if err != nil {
378					return err
379				}
380				opts.Edits.EnableProjects = &a
381			case optionVisibility:
382				visibilityOptions := []string{"public", "private", "internal"}
383				selected, err := p.Select("Visibility", strings.ToLower(r.Visibility), visibilityOptions)
384				if err != nil {
385					return err
386				}
387				confirmed := true
388				if visibilityOptions[selected] == "private" &&
389					(r.StargazerCount > 0 || r.Watchers.TotalCount > 0) {
390					cs := opts.IO.ColorScheme()
391					fmt.Fprintf(opts.IO.ErrOut, "%s Changing the repository visibility to private will cause permanent loss of stars and watchers.\n", cs.WarningIcon())
392					confirmed, err = p.Confirm("Do you want to change visibility to private?", false)
393					if err != nil {
394						return err
395					}
396				}
397				if confirmed {
398					opts.Edits.Visibility = &visibilityOptions[selected]
399				}
400			case optionMergeOptions:
401				var defaultMergeOptions []string
402				var selectedMergeOptions []string
403				if r.MergeCommitAllowed {
404					defaultMergeOptions = append(defaultMergeOptions, allowMergeCommits)
405				}
406				if r.SquashMergeAllowed {
407					defaultMergeOptions = append(defaultMergeOptions, allowSquashMerge)
408				}
409				if r.RebaseMergeAllowed {
410					defaultMergeOptions = append(defaultMergeOptions, allowRebaseMerge)
411				}
412				mergeOpts := []string{allowMergeCommits, allowSquashMerge, allowRebaseMerge}
413				selected, err := p.MultiSelect(
414					"Allowed merge strategies",
415					defaultMergeOptions,
416					mergeOpts)
417				if err != nil {
418					return err
419				}
420				for _, i := range selected {
421					selectedMergeOptions = append(selectedMergeOptions, mergeOpts[i])
422				}
423				enableMergeCommit := isIncluded(allowMergeCommits, selectedMergeOptions)
424				opts.Edits.EnableMergeCommit = &enableMergeCommit
425				enableSquashMerge := isIncluded(allowSquashMerge, selectedMergeOptions)
426				opts.Edits.EnableSquashMerge = &enableSquashMerge
427				enableRebaseMerge := isIncluded(allowRebaseMerge, selectedMergeOptions)
428				opts.Edits.EnableRebaseMerge = &enableRebaseMerge
429				if !enableMergeCommit && !enableSquashMerge && !enableRebaseMerge {
430					return fmt.Errorf("you need to allow at least one merge strategy")
431				}
432	
433				opts.Edits.EnableAutoMerge = &r.AutoMergeAllowed
434				c, err := p.Confirm("Enable Auto Merge?", r.AutoMergeAllowed)
435				if err != nil {
436					return err
437				}
438				opts.Edits.EnableAutoMerge = &c
439	
440				opts.Edits.DeleteBranchOnMerge = &r.DeleteBranchOnMerge
441				c, err = p.Confirm(
442					"Automatically delete head branches after merging?", r.DeleteBranchOnMerge)
443				if err != nil {
444					return err
445				}
446				opts.Edits.DeleteBranchOnMerge = &c
447			case optionTemplateRepo:
448				c, err := p.Confirm("Convert into a template repository?", r.IsTemplate)
449				if err != nil {
450					return err
451				}
452				opts.Edits.IsTemplate = &c
453			case optionAllowForking:
454				c, err := p.Confirm(
455					"Allow forking (of an organization repository)?",
456					r.ForkingAllowed)
457				if err != nil {
458					return err
459				}
460				opts.Edits.AllowForking = &c
461			}
462		}
463		return nil
464	}
465	
466	func parseTopics(s string) []string {
467		topics := strings.Split(s, ",")
468		for i, topic := range topics {
469			topics[i] = strings.TrimSpace(topic)
470		}
471		return topics
472	}
473	
474	func getTopics(ctx context.Context, httpClient *http.Client, repo ghrepo.Interface) ([]string, error) {
475		apiPath := fmt.Sprintf("repos/%s/%s/topics", repo.RepoOwner(), repo.RepoName())
476		req, err := http.NewRequestWithContext(ctx, "GET", ghinstance.RESTPrefix(repo.RepoHost())+apiPath, nil)
477		if err != nil {
478			return nil, err
479		}
480	
481		// "mercy-preview" is still needed for some GitHub Enterprise versions
482		req.Header.Set("Accept", "application/vnd.github.mercy-preview+json")
483		res, err := httpClient.Do(req)
484		if err != nil {
485			return nil, err
486		}
487		if res.StatusCode != http.StatusOK {
488			return nil, api.HandleHTTPError(res)
489		}
490	
491		var responseData struct {
492			Names []string `json:"names"`
493		}
494		dec := json.NewDecoder(res.Body)
495		err = dec.Decode(&responseData)
496		return responseData.Names, err
497	}
498	
499	func setTopics(ctx context.Context, httpClient *http.Client, repo ghrepo.Interface, topics []string) error {
500		payload := struct {
501			Names []string `json:"names"`
502		}{
503			Names: topics,
504		}
505		body := &bytes.Buffer{}
506		dec := json.NewEncoder(body)
507		if err := dec.Encode(&payload); err != nil {
508			return err
509		}
510	
511		apiPath := fmt.Sprintf("repos/%s/%s/topics", repo.RepoOwner(), repo.RepoName())
512		req, err := http.NewRequestWithContext(ctx, "PUT", ghinstance.RESTPrefix(repo.RepoHost())+apiPath, body)
513		if err != nil {
514			return err
515		}
516	
517		req.Header.Set("Content-type", "application/json")
518		// "mercy-preview" is still needed for some GitHub Enterprise versions
519		req.Header.Set("Accept", "application/vnd.github.mercy-preview+json")
520		res, err := httpClient.Do(req)
521		if err != nil {
522			return err
523		}
524	
525		if res.StatusCode != http.StatusOK {
526			return api.HandleHTTPError(res)
527		}
528	
529		if res.Body != nil {
530			_, _ = io.Copy(io.Discard, res.Body)
531		}
532	
533		return nil
534	}
535	
536	func isIncluded(value string, opts []string) bool {
537		for _, opt := range opts {
538			if strings.EqualFold(opt, value) {
539				return true
540			}
541		}
542		return false
543	}
